1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type QuoteStep = {
9	  op: "quote";
10	  items: Item[];
11	};
12	
13	export type Customer = {
14	  yearsWithMHPCO: number;
15	};
16	
17	export type Scenario = {
18	  customer: Customer;
19	  steps: QuoteStep[];
20	};
21	
22	export type ScenarioResults = {
23	  results: unknown[];
24	};
25	
26	const sum = (amounts: number[]): number =>
27	  amounts.reduce((total, amount) => total + amount, 0);
28	
29	const PROCESSING_FEE = 5;
30	
31	// Binary floating point makes exact multiples land a hair off (100 * 1.1 + 5 =
32	// 115.00000000000001); snap to cent precision so only genuine fractions round up.
33	const roundUpInMHPCOsFavour = (amount: number): number =>
34	  Math.ceil(Number(amount.toFixed(6)));
35	
36	// One entry per insurable type: every fact the office knows about a type lives
37	// here, so adding a type is a single edit.
38	type ItemKind = {
39	  basePremium: number;
40	  isComponent: boolean;
41	};
42	
43	const ITEM_CATALOGUE: Record<string, ItemKind> = {
44	  sword: { basePremium: 100, isComponent: false },
45	  amulet: { basePremium: 60, isComponent: false },
46	  staff: { basePremium: 80, isComponent: false },
47	  potion: { basePremium: 40, isComponent: false },
48	  rune: { basePremium: 25, isComponent: true },
49	  moonstone: { basePremium: 25, isComponent: true },
50	};
51	
52	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
53	
54	const kindOf = (item: Item): ItemKind => ITEM_CATALOGUE[item.type];
55	
56	const basePremiumOf = (item: Item): number => kindOf(item).basePremium;
57	
58	const BLOCK_SIZE = 3;
59	const BLOCK_BASE_PREMIUM = 60;
60	
61	const groupByType = (items: Item[]): Item[][] => {
62	  const itemsByType = new Map<string, Item[]>();
63	
64	  for (const item of items) {
65	    const sameTypeItems = itemsByType.get(item.type);
66	    if (sameTypeItems) sameTypeItems.push(item);
67	    else itemsByType.set(item.type, [item]);
68	  }
69	
70	  return [...itemsByType.values()];
71	};
72	
73	const isComponent = (item: Item): boolean => kindOf(item).isComponent;
74	
75	// A block is a special price for exactly 3 alike components; any other count,
76	// and any main item, is charged per item.
77	const sameTypeBasePremiumOf = (sameTypeItems: Item[]): number =>
78	  sameTypeItems.length === BLOCK_SIZE && isComponent(sameTypeItems[0])
79	    ? BLOCK_BASE_PREMIUM
80	    : sum(sameTypeItems.map(basePremiumOf));
81	
82	const policyBasePremiumOf = (items: Item[]): number =>
83	  sum(groupByType(items).map(sameTypeBasePremiumOf));
84	
85	const HIGH_ENCHANTMENT_THRESHOLD = 5;
86	
87	const isCursed = (item: Item): boolean => item.cursed === true;
88	
89	const isHighlyEnchanted = (item: Item): boolean =>
90	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
91	
92	// Item surcharges stack: each one whose condition holds contributes its rate.
93	const ITEM_SURCHARGES: { appliesTo: (item: Item) => boolean; rate: number }[] = [
94	  { appliesTo: isCursed, rate: 0.5 },
95	  { appliesTo: isHighlyEnchanted, rate: 0.3 },
96	];
97	
98	const itemSurchargeRateOf = (item: Item): number =>
99	  sum(
100	    ITEM_SURCHARGES.filter(({ appliesTo }) => appliesTo(item)).map(
101	      ({ rate }) => rate,
102	    ),
103	  );
104	
105	// Item-specific surcharges are charged on that item's own base premium, not on
106	// the policy total.
107	const itemSurchargesOf = (item: Item): number =>
108	  basePremiumOf(item) * itemSurchargeRateOf(item);
109	
110	const LOYALTY_DISCOUNT_RATE = 0.2;
111	const LOYALTY_YEARS_THRESHOLD = 2;
112	
113	const isLoyal = (customer: Customer): boolean =>
114	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
115	
116	const quote = (step: QuoteStep, customer: Customer): number => {
117	  const policyBasePremium = policyBasePremiumOf(step.items);
118	  const itemSurcharges = sum(step.items.map(itemSurchargesOf));
119	  const loyaltyDiscount = isLoyal(customer)
120	    ? policyBasePremium * LOYALTY_DISCOUNT_RATE
121	    : 0;
122	
123	  // Deliberately charged on the base premium alone, not on base + item
124	  // surcharges: a cursed sword quotes at 100 + 50 + 10 + 5 = 165, where the
125	  // 10 is 10 % of 100 rather than of 150.
126	  const firstInsuranceSurcharge =
127	    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
128	
129	  return roundUpInMHPCOsFavour(
130	    policyBasePremium +
131	      itemSurcharges -
132	      loyaltyDiscount +
133	      firstInsuranceSurcharge +
134	      PROCESSING_FEE,
135	  );
136	};
137	
138	export const runScenario = (scenario: Scenario): ScenarioResults => {
139	  return {
140	    results: scenario.steps.map((step) => ({
141	      premium: quote(step, scenario.customer),
142	    })),
143	  };
144	};
