// Negative because it is a discount, letting every policy-wide modifier be
// summed as a signed rate rather than sign-juggled at the call site.
const LOYALTY_DISCOUNT_RATE = -0.2;
const LOYALTY_YEARS_THRESHOLD = 2;

const isLoyal = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;

const loyaltyDiscountRateOf = (customer: Customer): number =>
  isLoyal(customer) ? LOYALTY_DISCOUNT_RATE : 0;

// Policy-wide modifiers are charged on the base premium alone, never on base +
// item surcharges: a cursed sword quotes at 100 + 50 + 10 + 5 = 165, where the
// 10 is 10 % of 100 rather than of 150.
const policyModifierRateOf = (customer: Customer): number =>
  FIRST_INSURANCE_SURCHARGE_RATE + loyaltyDiscountRateOf(customer);

const quote = (step: QuoteStep, customer: Customer): number => {
  const policyBasePremium = policyBasePremiumOf(step.items);
  const itemSurcharges = sum(step.items.map(itemSurchargesOf));
  const policyModifiers = policyBasePremium * policyModifierRateOf(customer);

  return roundUpInMHPCOsFavour(
    policyBasePremium + itemSurcharges + policyModifiers + PROCESSING_FEE,
  );
};
